  .badge{font-weight:600;font-size:.72rem;padding:.12rem .5rem;border-radius:6px}
  .badge.ok{color:var(--ok);background:#f0fdf4;border:1px solid #bfdbfe}
  .badge.err{color:var(--bad);background:#fee2e2;border:1px solid #fecaca}
  .res-enunciado{font-size:.92rem;margin:.65rem 0;line-height:1.5;color:var(--ink)}
  .res-alternativas{margin:.35rem 0}
