    font-size:.58rem;margin-left:3px}
  .mini-corr.certo{background:var(--ok-bg);color:var(--ok);border:1px solid var(--ok-bd)}
  .mini-corr.err{background:var(--bad-bg);color:var(--bad);border:1px solid var(--bad-bd)}
  .res-comentario{font-size:.84rem;color:var(--sub);line-height:1.5;margin-top:.3rem}

  /* ============ PRINT ============ */
