<script>
/* ==========================================================
   SIMULADO — ESTATUTO DOS SERVIDORES DE BERTIOGA
   (arquivo único: HTML + CSS + JS)
   ========================================================== */
'use strict';

const CONFIG = { perguntas: 20, tempo: 60, salva: true };

/* ---------------- QUESTÕES (gabarito = índice da opção correta, 0-based) ---------------- */
const QUES = [
  {
    id:1, tema:'Formas de provimento', tipo:'exceto',
    enunciado:'O edital do concurso da Prefeitura de Bertioga menciona, entre as formas de movimentação funcional, a promoção, a readaptação e a reversão. Sobre as formas de provimento de cargo público, assinale a alternativa INCORRETA:',
    opcoes:[
      {texto:'A nomeação é forma de provimento originária, precedida de aprovação em concurso público de provas ou de provas e títulos.',correta:false},
