/* ---------- HELPERS ---------- */
const LETRAS = ['A','B','C','D'];
function esc(s){ return String(s).replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch])); }
const CORES = { ok:'#0f766e', err:'#b91c1c' };
function agora(){ return Date.now(); }

/* ---------- DOM / ESTADO ---------- */
let indiceAtual = 0;           // posição atual no array QUES
let respostas   = {};           // id -> letra
let timerAtivo  = false;
let timerInicio = null;
let elementoRodadaAnterior = null; // para desfazer navegação
const WRAP = {};               // id -> {wrapper, elems[]}
const ELEMENTOS = [];         // [{id, wrap, elems}]

/* montagem das alternativas dinâmicas */
function criarOpcoes(q){
  if(WRAP[q.id]) return WRAP[q.id];
  const w = document.createElement('div');
  w.className = 'options-wrapper';
  w.dataset.q = q.id;
  const pos = [];
  q.opcoes.forEach((opt, pi) => {
    const el = document.createElement('div');
    el.className = 'option';
    el.id = `opt-${q.id}-a${pi+1}`;
    el.dataset.q = q.id;
    el.dataset.pos = pi;
    el.setAttribute('role','button');
    el.setAttribute('tabindex','0');
    const bd = document.createElement('span');
    bd.className = 'badge-hidden'; bd.hidden = true;
    el.appendChild(bd);
    el.innerHTML = `<span class="letra-badge">${LETRAS[pi]}</span><span class="txt">${esc(opt.texto)}</span>`;
    w.appendChild(el);
    pos.push(el);
  });
  WRAP[q.id] = w;
  ELEMENTOS.push({id: q.id, wrap: w, elems: pos});
  return w;
}
function getEle(qId, i){ return ELEMENTOS.find(x=>x.id===qId)?.elems[i]; }
function getPelosIds(ids){ return ids.map(id=>ELEMENTOS.find(x=>x.id===id)); }

/* ligação dos eventos das opções */
function ligarOpcoes(){
  ELEMENTOS.forEach(({wrap}) => {
    wrap.querySelectorAll('.option').forEach(el => {
      const i = Number(el.dataset.pos);            // posição na ordem A-D
      el.onclick  = e => tratarSelecao(el, i);
      el.addEventListener('keydown', e => {
        if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); tratarSelecao(el, i); }
      });
      el.addEventListener('touchstart', e => { e.preventDefault(); tratarSelecao(el, i); }, {passive:false});
    });
  });
}

/* ---- lógica principal ---- */
function podeResponder(qId){ return !(qId > 0 && (timerAtivo && !respostas[qId])); }

function marcarPendente(qId){
  const e = ELEMENTOS.find(x=>x.id===qId)?.elems; if(!e) return;
  ['A','B','C','D'].forEach((_,i)=>{
    const x = e[i];
    const escolhido = respostas[qId];
    const posL = escolhido ? LETRAS.indexOf(escolhido) : -1;
    x.classList.remove('lock-vis','certa','errada-eletida','escolhida','escolhida-certa','escolhida-errada','pendente-escolhida');
    x.classList.add('pendente');
    const b = x.querySelector('.badge-hidden'); b.hidden = false;
    b.textContent = (posL >= 0) ? '⏰' : '';
  });
}

function tratarSelecao(el, pos){
  const qId = +el.dataset.q;
  const i = Number(pos);
  if (podeResponder(qId) && (timerAtivo && !respostas[qId])) return; // bloqueado pelo cronômetro
  if (respostas[qId] !== undefined) return; // já respondida

  /* libera marcas anteriores dessa questão */
  if(getEle(qId)) {
    ['A','B','C','D'].forEach(() => {
      const x = getEle(qId,+this.dataset.pos) || getEle(qId); // simplificado abaixo
    });
    /* forma segura: reutilizar as refs já existentes */
  }
  const q = QUES[qId];
  const w = WRAP[q.id];
  if(!w){ w = criarOpcoes(q); }
  const e = w.elems;
  ['A','B','C','D'].forEach((_,ii)=>{
    const x = e[ii];
    x.classList.remove('lock-vis','certa','errada-eletida','escolhida','escolhida-certa','escolhida-errada','pendente-escolhida');
    x.disabled = false;
    x.querySelector('.badge-hidden').textContent = '';
  });

  const escolha = LETRAS[i];
  const correta = LETRAS[q.idxCorreta];
  aplicarMarca(q, escolha, correta);
  salvar(qId, escolha);
  mostrarFeedback(q, escolha, correta);
  controlarControles(qId, true);
  if (qId < QUES.length - 1) modoNormal();
}

function aplicarMarca(q, escolhida, correta){
  const e = WRAP[q.id].elems;
  ['A','B','C','D'].forEach((_,i)=>{
    const x = e[i];
    const eraCerta = (correta === LETRAS[i]);
    const eraSel   = (escolhida === LETRAS[i]);
    x.classList.remove('escolhida-certa','escolhida-errada','escolhida','errada-eletida','certa');
    if(eraSel){
      x.classList.add('escolhida');
      if(!eraCerta) x.classList.add('escolhida-errada');
      else x.classList.add('escolhida-certa');
    } else if(eraCerta){
      x.classList.add('certa');
    } else {
      x.classList.add('errada-eletida');
    }
    const bd = x.querySelector('.badge-hidden');
    bd.textContent = eraSel ? (eraCerta?'✔':'❌') : '';
  });
}

function salvar(qId, letra){
  respostas[qId] = letra;
  if (!CONFIG.salva){ return; }
  try{ localStorage.setItem('sim_bertioga', JSON.stringify(respostas)); }catch(e){}
  atualizarPill();
}

function atualizarPill(){
  const qtd = Object.keys(respostas).filter(k=>respostas[k]!==undefined).length;
  const p = document.getElementById('badgeSalvos');
  p.hidden = qtd === 0;
  if(qtd > 0) p.classList.add('pulsando');
}

function montarFeedback(q, escolhida, correta){
  const certL = LETRAS[q.idxCorreta];
  const linhas = [
    document.createElement('span'),
  ];
  linhas[0].className = 'linha';
  linhas[0].innerHTML = `Alternativa correta: ${certL} — <strong>${esc(q.opcoes[q.idxCorreta].texto)}</strong>`;
  const extras = [];
  if(q.tipo === 'exceto'){
    extras.push(`<em>A questão pede o item que <strong>não</strong> corresponde ao Estatuto — o destacado é justamente a exceção solicitada.</em>`);
  } else {
    extras.push('Os demais itens tratam de outras situações ou divergem das regras do Estatuto.');
  }
  const ok = (escolhida !== undefined) && (escolhida === certL);
  const msg = document.createElement('span');
  msg.className = ok ? 'msg-ok' : 'msg-err';
  msg.textContent = ok ? '✅ Boa escolha!' : `❌ Atenção: revise o conteúdo sobre <em>${esc(q.tema)}</em>.`;
  const p = document.getElementById('fb');
  p.innerHTML = '';
  p.append(...linhas, ...(extras.map(t=>{const s=document.createElement('span'); s.innerHTML=t; return s;})), msg);
  p.className = 'feedback-panel fab';
  return p;
}

function desbloquearVisual(qIds){
  qIds.forEach(qId=>{
    const e = ELEMENTOS.find(x=>x.id===qId); if(!e) return;
    ['A','B','C','D'].forEach(ii=>{
      const x = e.elems[ii];
      x.classList.remove('lock-vis','pendente','pendente-escolhida');
      x.querySelector('.badge-hidden').textContent = '';
      x.disabled = false;
    });
  });
}

function marcarComoPendentes(qIds){
  qIds.forEach(qId=>{
    const e = ELEMENTOS.find(x=>x.id===qId); if(!e) return;
    ['A','B','C','D'].forEach((_,ii)=>{
      const x = e.elems[ii];
      x.classList.remove('lock-vis','certa','errada-eletida','escolhida','escolhida-certa','escolhida-errada','pendente-escolhida');
      x.classList.add('pendente');
      const escolhido = respostas[qId]; const pl = escolhido ? LETRAS.indexOf(escolhido):-1;
      const b = x.querySelector('.badge-hidden'); b.hidden=false; b.textContent = (pl>=0) ? '⏰' : '';
    });
  });
}

/* -------- NAVEGAÇÃO -------- */
let modoFinalFechado = false;

function modoNormal(){
  const fin = document.getElementById('bnFinish');
  const nxt = document.getElementById('bnNext');
  if(fin.hidden){
    fin.hidden = false;
    const fbt = document.createElement('button');
    fbt.id = 'bnFinish2';
    fbt.className = 'btn finish-btn';
    fbt.textContent = 'Ver resultado 🏁';
    nxt.parentNode.replaceChild(fbt, nxt);
    modoFinalFechado = true;
  } else {
    fin.hidden = true;
    nxt.classList.remove('finish-btn');
    nxt.textContent = 'Próxima ▶';
    modoFinalFechado = false;
  }
}

function controlarControles(cur, respondeu){
  const prev = document.getElementById('bnPrev');
  const nxt  = document.getElementById('bnNext');
  const ult  = cur === QUES.length - 1;
  prev.disabled = (cur === 0);
  if(respondeu){
    if(ult){
      if(!modoFinalFechado){ modoFinalFechado = true; nxt.parentNode.replaceChild(document.getElementById('bnFinish2'), nxt); }
      prev.textContent = '‹ Rever';
      nxt.classList.add('finish-btn');
    } else {
      nxt.classList.remove('finish-btn');
      const blocado = (timerAtivo && !respostas[cur]);
      nxt.disabled = blocado;
      nxt.textContent = blocado ? 'Responda antes de avançar' : 'Próxima ▶';
    }
  } else {
    nxt.disabled = true;
    const msg = document.getElementById('blkMsg');
    msg.hidden = !(timerAtivo && cur > 0 && !respostas[cur]);
    if(!timerAtivo || cur <= 0){ nxt.textContent = 'Próxima ▶'; }
    else nxt.textContent = 'Cronômetro ativo — responda para avançar';
    prev.disabled = false;
  }
}

function anterior(){
  if(indiceAtual <= 0) return;
  const q = QUES[indiceAtual-1];
  render(indiceAtual-1);
  desbloquearVisual([indiceAtual-1]);
  indiceAtual = indiceAtual-1;
  controlarControles(indiceAtual, respostas[indiceAtual]>==undefined);
  atualizarHUD();
  focoPrimeira();
}

function avancar(qId){
  if(qId >= QUES.length){ return concluir(); }
  desbloquearVisual([qId]);
  render(qId);
  indiceAtual++;
  controlarControles(qId, respostas[qId]>==undefined);
  atualizarHUD();
  focoPrimeira();
  if(qId < QUES.length-1) modoNormal();
}

function focoPrimeira(){
  const q = QUES[indiceAtual];
  const w = WRAP[q.id] || criarOpcoes(q);
  const alvo = w.querySelector(':scope > .option:not(.lock-vis):not(.pendente)');
  if(alvo) alvo.focus();
}

function atualizarHUD(){
  const answered = Object.keys(respostas).filter(k=>respostas[k]!==undefined && respostas[k]!==null).length;
  const bar = document.getElementById('bar');
  const pct = Math.round((answered/QUES.length)*100);
  bar.style.width = pct + '%';
  bar.classList.toggle('cheio', pct === 100);
  document.getElementById('qNum').textContent = indiceAtual+1;
  document.getElementById('qTopic').textContent = QUES[indiceAtual]?.tema || '—';
  const msg = document.getElementById('blkMsg');
  msg.hidden = !(timerAtivo && indiceAtual > 0 && !respostas[indiceAtual]);
}

/* -------- FEEDBACK -------- */
function mostrarFeedback(q, escolhida, correta){
  const fb = document.getElementById('fb');
  fb.classList.remove('hidden');
  fb.innerHTML = '';
  fb.append(montarFeedback(q, escolhida, correta));
  fb.style.opacity = '1';
  setTimeout(() => {
    const cur = QUES.indexOf(q);
    if(cur < QUES.length-1) modoNormal(); // mantém navegação normal
  }, 1300);
}

/* -------- CONCLUIR / RESULTADO -------- */
function finalizar(){
  estadoConcluir();
  const rv = document.getElementById('resultado');
  rv.classList.add('active');
  rv.hidden = false;
  document.getElementById('quiz').classList.remove('active');
  document.getElementById('quiz').hidden = true;
  rv.scrollIntoView({behavior:'smooth', block:'nearest'});
  focoPrimeira(); // foco no score
}

function estadoConcluir(){
  let acertos = 0, pendentes = 0;
  QUES.forEach((q,i)=>{
    const g = respostas[i];
    if(g === undefined || g === null) pendentes++;
    else if(g === LETRAS[q.idxCorreta]) acertos++;
  });
  const erros = QUES.length - acertos - pendentes;
  const pct = Math.round((acertos/QUES.length)*100);
  const tempo = (timerInicio ? (agora()-timerInicio) : 0);
  const tier = pct >= 90 ? 'diamante' : pct >= 75 ? 'ouro' : pct >= 50 ? 'prata' : pct >= 25 ? 'bronze' : 'ruim';
  // salvar resultado global (opcional)
  localStorage.setItem('sim_resultado', JSON.stringify({acertos, erros, pct, tier, tempo}));
  document.getElementById('scoreVal').textContent = acertos;
  document.getElementById('pctVal').textContent = pct + '%';
  const emoji = {'diamante':'🏆','ouro':'🥇','prata':'🥈','bronze':'🥉','ruim':'😞'}[tier];
  const mEl = document.getElementById('medalEmoji');
  mEl.textContent = emoji;
  mEl.className = `.medal .${tier}`;
  document.getElementById('statAcertos').textContent = acertos;
  document.getElementById('statErros').textContent = erros;
  document.getElementById('statTempo').textContent = fmtMMSS(tempo);
  document.getElementById('statDesc').textContent = pct === 100 ? 'Impecável!' : pct >= 90 ? 'Excelente!' : pct >= 75 ? 'Muito bom!' : pct >= 50 ? 'Bom — revise os erros' : 'Abaixo do esperado — estude mais';
  gerarSugestoes(tier, acertos, QUES.length, tempo);
}

function fmtMMSS(ms){
  const d = Math.floor(ms/60000), m = Math.floor((ms%60000)/1000), s = Math.floor((ms%1000)/10);
  return `${d.toString().padStart(2,'0')}:${m.toString().padStart(2,'0')}.${s.toString().padStart(2,'0')}`;
}

function gerarSugestoes(tier, acertos, total, tempo){
  const cont = {};
  QUES.forEach((q,i)=>{
    const g = respostas[i];
    if(g !== undefined && g !== LETRAS[q.idxCorreta]){
      (cont[q.temal] ||=0); cont[q.tema] = (cont[q.tema]||0)+1;
    }
  });
  const cards = [];
  if(!Object.keys(cont).length){
    document.getElementById('suggestions').innerHTML = '<p class="tit">Parabéns — domínio amplo!</p><p>Mantenha a revisão de temas atuais e novas tendências de prova.</p>';
    return;
  }
  const entr = Object.entries(cont).sort((a,b)=>b[1]-a[1]);
  let txt = 'Pontos que pedem reforço (erros registrados):';
  entr.forEach(([tema,n]) => { txt += `\n• <strong>${tema}</strong> (${n} erro/s)`; });
  txt += `<br><p>Dica: releia os capítulos do Estatuto relacionados a esses temas e resolva questões comentadas desses tópicos antes da prova real.</p>`;
  document.getElementById('suggestions').innerHTML = `<p class="tit">${txt}</p>`;
}

function renderizarCard(q, i){
  const got = respostas[i];
  const certaL = LETRAS[q.idxCorreta];
  const acertou = (got !== undefined && got !== null && got === certaL);
  const pendente = got === null || got === undefined;
  let status = '';
  let badge = '';
  if(acertou){
    status = `<span class="dot ok">✔</span> Você marcou <code>${got}</code> — <span class="badge ok">CERTA (+1)</span>`;
  } else if(pendente){
    status = `<span class="dot x">⏰</span> Em branco (cronômetro ou pulo) — <span class="badge err">SEM RESPOSTA</span>`;
  } else {
    status = `<span class="dot x">✘</span> Você marcou <code>${got}</code> — <span class="badge err">ERRADA</span>`;
  }
  const cor = acertou ? 'certo' : 'err';
  return `
  <article class="res-card">
    <div class="res-head">
      <span class="res-titulo">#${i+1} — ${esc(q.tema)}</span>
      <div class="res-status">${status}</div>
    </div>
    <p class="res-enunciado">${esc(q.enunciado)}</p>
    <div class="res-alternativas">
      ${['A','B','C','D'].map((L,p)=>{
        const mk = acertou && L===certaL ? ' ✔' : ' ✘';
        return `<div class="mini-opt"><span class="ml">${esc(L)}</span>${esc(q.opcoes[p].texto)}${mk}<span class="mini-corr ${cor}"></span></div>`;
      }).join('\n')}
    </div>
    <p class="res-comentario">${esc(q.comentario)}</p>
  </article>`;
}

function renderizarResultado(){
  const grid = document.getElementById('revGrid');
  grid.innerHTML = '';
  QUES.forEach((q,i)=>{
    const el = document.createElement('div');
    el.innerHTML = renderizarCard(q, i);
    grid.appendChild(el);
  });
}

/* -------- TIMER -------- */
function iniciarRelogio(dur){
  timerAtivo = true;
  timerInicio = agora();
  const el = document.getElementById('clock');
  el.classList.add('show');
  el.hidden = false;
  let raf = null;
  const tick = () => {
    if(!timerAtivo || !el.classList.contains('show')){ cancelarRAF(); return; }
    const resto = agora()-timerInicio;
    el.textContent = fmtMMSS(resto);
    raf = requestAnimationFrame(tick);
  };
  requestAnimationFrame(tick);
  timerIntId = setInterval(()=> requestAnimationFrame(tick), 1000);
}
function pararRelogio(){
  if(!timerAtivo) return;
  clearInterval(timerIntId);
  cancelAnimationFrame(raf);
  timerAtivo = false;
  document.getElementById('clock').classList.remove('show');
  document.getElementById('clock').hidden = true;
}

/* -------- TEMA -------- */
const btnTema = document.querySelector('.theme-btn');
btnTema.addEventListener('click', () => {
  const atual = document.documentElement.getAttribute('data-theme') || 'light';
  const prox = atual === 'light' ? 'dark' : 'light';
  document.documentElement.setAttribute('data-theme', prox);
  localStorage.setItem('tema', prox);
});

/* -------- SALVAMENTO DO INDICADOR -------- */
let salvadoInicial = Object.keys(respostas).length > 0;
const pill = document.getElementById('badgeSalvos');
if(salvadoInicial) pill.classList.add('pulsando');

/* -------- EVENTOS PRINCIPAIS -------- */
function ligarEventos(){
  document.getElementById('bnStart').addEventListener('click', () => {
    document.getElementById('instrucoes').hidden = true;
    salvar(undefined, null); // neutro
    if(Config?.tempo > 0) iniciarRelogio(CONFIG.tempo); else pararRelogio();
    document.getElementById('quiz').classList.add('active');
    document.getElementById('quiz').hidden = false;
    document.getElementById('resultado').hidden = false; // não importa
    document.getElementById('resultado').classList.add('active');
    // resetar modo final se algum estado ficou
    modoNormal();
    focoPrimeira();
  });
  document.getElementById('timerToggle').addEventListener('click', () => {
    const antes = timerAtivo;
    timerAtivo = !antes;
    const troc = document.getElementById('timerToggle');
    troc.classList.toggle('on', timerAtivo);
    troc.textContent = timerAtivo ? '⏱ Ativo (pressione para parar)' : '⏱ Desativado';
    if(timerAtivo){
      timerInicio = agora();
      iniciarRelogio(CONFIG.tempo);
    } else{
      pararRelogio();
    }
  });
  document.getElementById('redoBtn').addEventListener('click', () => resetTudo());
  document.getElementById('bnPrev').addEventListener('click', anterior);
  document.getElementById('bnFinish').addEventListener('click', finalizar);
  ligarOpcoes();
}

/* -------- RESET (nova rodada) -------- */
function resetTudo(){
  localStorage.removeItem('sim_bertioga');
  localStorage.removeItem('sim_resultado');
  respostas = {};
  timerAtivo = false;
  pararRelogio();
  indiceAtual = 0;
  modoFinalFechado = false;
  if(ElementOS.length){ ELEMENTOS.forEach(e=>{ ['A','B','C','D'].forEach(()=>{ e.elems[Math.min(+e.elems.indexOf(e.parent.childNodes)-1 ||0)]... })}); } }
  /* simplificação: limpa classes dos elementos existentes */
  ELEMENTOS.forEach(e=>{
    ['A','B','C','D'].forEach(ii=>{
      const x = e.elems[ii];
      if(x){ x.classList.remove('certa','errada-eletida','escolhida','escolhida-certa','escolhida-errada','pendente','pendente-escolhida','lock-vis'); x.querySelector('.badge-hidden').textContent=''; x.disabled=false; }
    });
  });
  document.getElementById('bar').style.width='0%';
  // re-hybrate componentes visuais
  document.querySelectorAll('.option').forEach(o=> o.classList.remove('certa','errada-eletida','escolhida','escolhida-certa','escolhida-errada','pendente','pendente-escolhida','lock-vis'));
  document.querySelectorAll('.badge-hidden').forEach(b=>{ b.hidden=true; b.textContent=''; })
  document.getElementById('fb').classList.add('hidden');
  document.getElementById('blkMsg').hidden = true;
  if(pill) pill.hidden = true;
  document.getElementById('bnPrev').textContent = '◀ Anterior';
  document.getElementById('bnNext').textContent = 'Próxima ▶';
  document.getElementById('bnFinish').hidden = true;
  document.getElementById('redoBtn').textContent = 'Nova rodada ↻';
}

/* ------------- BOOTSTRAP ------------- */
try{
  const pref = localStorage.getItem('tema');
  if(pref) document.documentElement.setAttribute('data-theme', pref);
  else if('prefers-color-scheme' in window) document.documentElement.setAttribute('data-theme', window.matchMedia('(prefers-color-scheme:dark)').matches ? 'dark' : 'light');
}catch(e){}
const hist = (() => {
  try{
    const s = localStorage.getItem('sim_bertioga');
    if(!s) return [];
    const d = JSON.parse(s);
    d.forEach(r => { if(typeof r.i === 'number' && LETRAS.indexOf(r.letra)>=0) respostas[r.i] = r.letra; });
  }catch(e){}
  return Object.keys(respostas).length > 0 ? respostas : [];
})();
if(hist.length){
  historicoCadaUm(); // aplica respostas salvas visualmente
}
ligarEventos();

/* aplica respostas salvas no visual */
function historicoCadaUm(){
  ['A','B','C','D'].forEach(letra => {
    const found = ELEMENTOS.find(x => x.elems.some(e=>e.dataset.li === (['A','B','C','D'].indexOf(letra)+1)));
    if(!found) return;
    const qId = found.wrap.dataset.q;
    if(respostas[qId] !== letra) return; // muda depois, ignora
  });
  // abordagem mais robusta: iterar respostas salvas
  Object.keys(respostas).forEach(qId => {
    if(respostas[qId] === undefined) return;
    const l = respostas[qId];
    const posi = ['A','B','C','D'].indexOf(l);
    const w = WRAP[qId] || criarOpcoes(QUES[qId]);
    const el = w.elems[posi];
    if(!el) return;
    const prev = respostas[qId]; // já correto, apenas estiliza
    aplicarMarca(QUES[qId], l, LETRAS[QUES[qId].idxCorreta]);
  });
  atualizarPill();
}
/* (acima o loop não funciona bem com dataset li; corrigir com mapa alternativo) */
/* Mapa confiável: numeração sequencial */
const NUM_MAP = {};
QUES.forEach((q,i)=>{ ['A','B','C','D'].forEach((letra,pos)=>{ NUM_MAP[`${q.id}_${pos+1}`]=letra; }); });
NUM_MAP.each=function(o){for(const k in o)o[k]=typeof o[k]!=='function'&&o[k]!=null&&(NUM_MAP.each(o[k]), o[k]);return this};
Object.keys(NUM_MAP).forEach(k=>{ const[qId,pos]=k.split('_'); const l=NUM_MAP[k]; const w=WRAP[qId]||criarOpcoes(QUES[qId]); const e=w.elems[+pos-1]; if(e && respostas[qId]====l){ aplicarMarca(QUES[qId],l,LETRAS[QUES[qId].idxCorreta]); } });
if(!hist.length && Object.keys(respostas).length===0) document.getElementById('qNum').textContent = '1';

/* Corrigir estado do botão "Próxima" e controles iniciais */
document.getElementById('bnPrev').disabled = true;
document.getElementById('bnNext').textContent = 'Próxima ▶';
document.getElementById('bnNext').disabled = false;
atualizarHUD();
ligarOpcoes();
focoPrimeira();
</script>
