    --ok:#0f766e; --ok-bg:#ecfdf5; --ok-bd:#22c55e;
    --bad:#b91c1c; --bad-bg:#fef2f2; --bad-bd:#ef4444;
    --rad:18px; --shadow:0 8px 32px rgba(15,23,42,.07);
  }
  [data-theme="dark"]{
    --bg:#0c121f; --surface:#16202b; --paper:#1e2b3a;
    --ink:#e8ecf1; --sub:#9aa7b4; --line:#2a3748;
    --brand:#818cf8; --brand-lite:#1a1533; --brand-glow:0 0 0 4px rgba(129,140,248,.35);
    --ok:#34d399; --ok-bg:#052e16; --ok-bd:#4ade80;
    --bad:#f87171; --bad-bg:#450a0a; --bad-bd:#fca5a5;
  }

  body{
    font-family:'Inter',system-ui,-apple-system,'Segoe UI',sans-serif;
    background:radial-gradient(circle at 18% 0%, #1e2a4a, var(--bg));
    color:var(--ink); min-height:100vh; display:flex; flex-direction:column; margin:0; padding:0;
  }

  /* ============ CABEÇALHO ============ */
  .topbar{display:flex; align-items:center; gap:14px; padding:.75rem 1.2rem; flex-shrink:0; position:relative}
  .theme-btn{width:38px;height:38px;border-radius:50%;background:var(--surface);color:var(--ink);
    border:1px solid var(--line);cursor:pointer;display:flex;align-items:center;justify-content:center;
    font-size:13px;transition:.2s}
  .brand{flex:1;display:flex;align-items:center;gap:10px}
  .logo{width:38px;height:38px;border-radius:12px;background:var(--brand-lite);color:var(--brand);
    display:flex;align-items:center;justify-content:center;font-weight:800;font-size:17px}
  .brand h1{name}{font-size:1.25rem;font-weight:700;letter-spacing:-.02em;margin:0}
  .brand .version{font-size:.78rem;color:var(--sub);line-height:1.5;margin-top:.2rem}
  .meta-right{display:flex;align-items:center;gap:8px}
  .badge{font-size:.7rem;padding:.2rem .65rem;border-radius:999px;background:var(--brand-lite);
    color:var(--brand);font-weight:600}
  .pulsando{animation:piscar .9s infinite}
  .timer-toggle{font-size:.85rem;padding:.45rem .9rem;border:1px solid var(--line);border-radius:999px;
    background:var(--surface);color:var(--ink);cursor:pointer;font-weight:500;white-space:nowrap}
  .timer-toggle.on{background:var(--ok-bg);color:var(--ok);border-color:var(--ok-bd);
    box-shadow:0 0 0 4px var(--brand-glow)}

  /* ============ INSTRUÇÕES ============ */
  .instrucoes{background:var(--paper);border:1px solid var(--line);border-radius:var(--rad);
    padding:1.3rem 1.2rem;margin:1rem auto;max-width:740px;width:100%;flex:0 0 auto}
  .instrucoes h2{font-size:1rem;margin:0 0 .7rem;color:var(--ink)}
  .instrucoes ul{margin:.3rem 0 .6rem 1.2rem;padding-left:1.35rem;font-size:.88rem;line-height:1.75;color:var(--sub)}
  .instrucoes li{margin:.3rem 0}
  .start-btn{display:block;width:100%;padding:.8rem 1.2rem;font-size:1.02rem;font-weight:700;
    background:var(--brand);color:#fff;border:none;border-radius:14px;cursor:pointer;
    box-shadow:var(--shadow);margin-top:.7rem;text-align:left;transition:.2s}
  .start-btn:hover{transform:translateY(-1px);box-shadow:0 8px 26px rgba(67,56,202,.45)}
  .start-btn:active{transform:scale(.97)}

  /* ============ ÁREA DA PROVA ============ */
  .quiz{max-width:740px;margin:auto;padding:1rem 0 2rem;flex:1;display:none}
  .quiz.active{display:block}
  .hud{display:flex;align-items:stretch;gap:.75rem;flex-wrap:wrap}
  .hud-left{flex:1.25;min-width:150px;display:flex;flex-direction:column}
  .qrow{display:flex;align-items:baseline;gap:5px;font-size:.82rem;font-weight:700;color:var(--ink)}
  .topic{font-size:.85rem;color:var(--brand);font-weight:600;text-transform:uppercase;letter-spacing:.05em;margin-top:.35rem}
  .progress-wrap{flex:1;height:7px;border-radius:999px;background:var(--line);min-width:90px;overflow:hidden}
  .progress-bar{height:100%;background:linear-gradient(90deg,#c084fc,#818cf8);border-radius:999px;width:0%;
    transition:width .35s ease, background .6s ease-out;position:relative}
  .progress-bar::after{content:'';position:absolute inset;-webkit-inset:-1px;background:#fff;border-radius:1px;opacity:.95}
  .progress-bar.cheiro::after{opacity:1}
  .timer-wrap{text-align:right;min-width:110px}
  .clock{display:none;font-family:monospace;font-variant-numeric:tabular-nums;font-size:1rem;font-weight:700;
    color:var(--ink);white-space:nowrap}
  .clock.show{display:inline-block}
  .hud-actions{margin-top:.35rem;display:flex;gap:6px;flex-shrink:0}
  .message-block{font-size:.78rem;color:var(--sub);min-height:1.5rem;text-align:center;font-style:italic}

  .aq{padding-top:.8rem}
  .enunciado{font-size:1rem;line-height:1.6;color:var(--ink);background:var(--paper);border:1px solid var(--line);
    border-radius:12px;padding:.9rem 1rem}
  .enunciado strong{color:var(--brand)}
  .options-wrapper{margin-top:.9rem;font-size:.94rem}
  .option{display:flex;align-items:center;gap:9px;padding:.65rem .95rem;border:1.5px solid var(--line);
    background:var(--surface);color:var(--ink);border-radius:12px;cursor:pointer;font-size:.92rem;
    line-height:1.45;transition:.18s;position:relative}
  .letter-badge{display:inline-flex;align-items:center;justify-content:center;width:26px;height:26px;border-radius:50%;
    font-weight:700;font-size:.8rem;color:#fff;background:var(--brand);flex:none}
  .badge-hidden{font-size:.7rem;padding:.15rem .4rem;border-radius:5px;font-weight:600;vertical-align:middle;
    margin-left:6px;background:#f0f4ff;color:var(--brand)}
  .option:hover:not(.lock-vis){transform:translateY(-1.5px);box-shadow:0 8px 22px rgba(15,23,42,.1),0 0 0 0 transparent}
  .option:active{transform:scale(.97);box-shadow:none}
  .option:disabled, .option.lock-vis{cursor:wait;opacity:.55;transform:none;pointer-events:none}
  .option.escolhida{border-color:var(--brand);outline:2px solid var(--brand);outline-offset:-2px}
  .option.escolhida-certa{background:var(--ok-bg);border-color:var(--ok-bd);color:var(--ok);box-shadow:0 0 0 4px rgba(15,118,110,.15)}
  .option.escolhida-errada{background:var(--bad-bg);border-color:var(--bad-bd);color:var(--bad);
    box-shadow:inset 0 0 0 3px rgba(185,28,28,.25)}
  .option.certa{background:var(--ok-bg);border-color:var(--ok-bd);color:var(--ok)}
  .option.errada-eletida{background:var(--bad-bg);border-color:var(--bad-bd);color:var(--bad)}

  .feedback-panel{margin-top:.85rem;padding:.75rem .9rem;background:var(--paper);border:1px dashed var(--line);
    border-radius:12px;font-size:.92rem;line-height:1.55;color:var(--ink);transition:opacity .25s;
    min-height:1.4rem}
  .feedback-panel.hidden{opacity:0}
  .linha{margin-bottom:.05rem}
  .msg-ok{color:var(--ok);font-weight:600}
  .msg-err{color:var(--bad);font-weight:600}
  .lock-msg{font-size:.78rem;color:var(--bad);min-height:1.6rem;text-align:center;padding:.4rem}

  /* ============ RESULTADO ============ */
  .resultado{display:none;max-width:740px;margin:auto;padding:1.2rem 0 2rem;flex:1}
  .resultado.active{display:block}
  .score-top{background:var(--paper);border-radius:var(--rad);padding:1.2rem 1.4rem;margin-bottom:1rem;
    box-shadow:var(--shadow)}
  .score-top h2{font-size:1rem;margin:0 0 .4rem}
  .score-big{display:flex;align-items:baseline;gap:8px;font-size:2.1rem;font-weight:800}
  .score-label{color:var(--sub);font-weight:400;font-size:1.1rem}
  .score-pct{display:flex;align-items:center;gap:6px;font-size:1rem;margin-top:.35rem}
  .medal{display:inline-block;font-size:1.7rem;margin:1rem -1.4rem 0}
  .stats{display:grid;grid-template-columns:repeat(4,1fr);gap:.7rem;margin-bottom:1rem}
  .stats .s{display:flex;flex-direction:column;gap:.22rem;font-size:.85rem}
  .stats .v{font-weight:700;color:var(--brand);font-variant-numeric:tabular-nums}
  .tm .v{color:var(--brand)}
  .suggestions{font-size:.86rem;color:var(--sub);line-height:1.65}
  .suggestions .tit{font-weight:600;color:var(--ink);margin-bottom:.4rem}
  .redo-btn{width:100%;padding:.6rem 0;text-align:center;font-weight:600;border-radius:12px;
    background:var(--surface);color:var(--ink);border:1px solid var(--line);cursor:pointer;font-size:.9rem;
    display:block;margin-top:1rem}
  .redo-btn:hover{background:var(--brand);color:#fff;border-color:var(--brand);transform:translateY(-1px)}

  .rev-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:.75rem;margin-top:.8rem}
  @media(max-width:560px){ .rev-grid{grid-template-columns:1fr} .score-top{padding:.9rem} }
  .res-card{background:var(--paper);border:1px solid var(--line);border-radius:12px;padding:.85rem;margin:.5rem 0;
    break-inside:avoid;page-break-inside:avoid}
  .res-head{display:flex;justify-content:space-between;align-items:flex-start;gap:8px;font-size:.88rem}
  .res-titulo{font-weight:700;color:var(--ink)}
  .res-status{font-size:.8rem;display:flex;align-items:center;gap:5px}
  .dot{width:17px;height:17px;border-radius:50%;font-size:.68rem;font-weight:700;display:inline-flex;align-items:center;justify-content:center}
  .dot.ok{background:var(--ok);color:#fff}
  .dot.err{background:var(--bad);color:#fff}
  .dot.x{background:#888;color:#fff}
  .badge{font-weight:600;font-size:.72rem;padding:.12rem .5rem;border-radius:6px}
  .badge.ok{color:var(--ok);background:#f0fdf4;border:1px solid #bfdbfe}
  .badge.err{color:var(--bad);background:#fee2e2;border:1px solid #fecaca}
  .res-enunciado{font-size:.92rem;margin:.65rem 0;line-height:1.5;color:var(--ink)}
  .res-alternativas{margin:.35rem 0}
  .mini-opt{display:inline-flex;align-items:center;gap:4px;font-size:.74rem;padding:.18rem .55rem;
    border:1px solid var(--line);border-radius:6px;background:var(--surface);margin:.06rem 0}
  .mini-opt:last-child{margin:0}
  .ml{font-weight:700;color:var(--brand)}
  .mini-corr{width:13px;height:13px;border-radius:50%;display:inline-flex;align-items:center;justify-content:center;
    font-size:.58rem;margin-left:3px}
  .mini-corr.certo{background:var(--ok-bg);color:var(--ok);border:1px solid var(--ok-bd)}
  .mini-corr.err{background:var(--bad-bg);color:var(--bad);border:1px solid var(--bad-bd)}
  .res-comentario{font-size:.84rem;color:var(--sub);line-height:1.5;margin-top:.3rem}

  /* ============ PRINT ============ */
  @media print{
    body{background:#fff;color:#000;font-size:13px}
    .topbar,.instrucoes,.hud-actions,.lock-msg,.badge,.suggestions,.redo-btn,.theme-btn,.timer-toggle,.progress-wrap{display:none!important}
    .quiz,.resultado{display:block;margin:0 1.2cm;padding:0;max-width:none}
    .options-wrapper,.res-card{break-inside:avoid;page-break-inside:avoid}
    .option{border:1px solid #000;background:#fff;box-shadow:none}
    .feedback-panel{border-style:solid;border-color:#000;background:#f7f7f7}
    .res-card{border:1px solid #000;margin:.5rem 0;background:#fff}
  }

  @keyframes piscar{0%,100%{opacity:1}50%{opacity:.55}}
  @keyframes fade-in{from{opacity:0;transform:translateY(4px)}to{opacity:1;transform:none}}
  .fab{animation:fade-in .3s ease}
  .option:first-of-type{transition-delay:.04s}
  .option:nth-of-type(2){transition-delay:.06s}
  .option:nth-of-type(3){transition-delay:.08s}
  .option:nth-of-type(4){transition-delay:.1s}
</style>
</head>
<body>

<!-- CABEÇALHO -->
<header class="topbar">
  <button class="theme-btn" aria-label="Trocar tema claro/escuro" title="Tema">
    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="5"/><line x1="12" y1="1" x2="12" y2="3"/><line x1="12" y1="21" x2="12" y2="23"/><line x1="4.22" y1="4.22 l" x2="19.78" y2="19.78"/><line x1="19.78" y1="4.22 l" x2="4.22" y2="19.78"/></svg>
  </button>
  <div class="brand">
    <div class="logo">📖</div>
