      <h2>Sua nota</h2>
      <div class="score-big"><span class="score-val" id="scoreVal"></span><span class="score-label">/ 20</span></div>
      <div class="score-pct"><span class="pct-val" id="pctVal">0%</span><span>de acerto</span></div>
      <div class="medal"><span class="" id="medalEmoji"></span></div>
      <div class="stats">
        <div class="s"><span>Acertos</span><strong class="v" id="statAcertos"></strong></div>
        <div class="s"><span>Erros/Em branco</span><strong class="v" id="statErros"></strong></div>
        <div class="s tm"><span>Tempo (se ativado)</span><strong class="v" id="statTempo"></strong></div>
        <div class="s"><span>Desempenho</span><strong class="v" id="statDesc"></span></div>
      </div>
      <p class="suggestions" id="suggestions"></p>
      <button class="redo-btn" id="redoBtn">Nova rodada ↻</button>
    </div>
    <div class="rev-grid" role="list" aria-label="Análise detalhada das questões"></div>
  </section>
</main>

<script>
